150	// makeTestJWT builds a three-segment JWT (alg:HS256 so ParseClaims accepts it)
151	// carrying the given aud. The signature segment is filler — the env-token path
152	// reads the aud unverified and gates it on cluster-advertised cores, never on
153	// the signature.
154	func makeTestJWT(t *testing.T, aud string) string {
155		t.Helper()
156		enc := base64.RawURLEncoding
157		header := enc.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
158		payload := enc.EncodeToString([]byte(fmt.Sprintf(`{"sub":"ci-runner","aud":%q}`, aud)))
159		return header + "." + payload + "." + enc.EncodeToString([]byte("sig"))
160	}
