163	// cores over TLS, returning the server and the host:port to use as clusterHost.
164	func wellKnownServer(t *testing.T, cores []string) (*httptest.Server, string) {
165		t.Helper()
166		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
167			if r.URL.Path != "/.well-known/entire-cluster.json" {
168				http.NotFound(w, r)
